"use client";

import * as React from "react";

import {
  normalizePincode,
  type PincodeResult,
  validatePincode,
} from "../../lib/pincode";
import { cn, controlClasses, Field, FieldBadge, useFieldState } from "./field";

export interface PincodeInputProps
  extends Omit<
    React.ComponentProps<"input">,
    "value" | "defaultValue" | "onChange" | "type"
  > {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  onValidationChange?: (result: PincodeResult) => void;
  validateOn?: "blur" | "change";
  /** Show the derived postal zone. Default `true`. */
  showZone?: boolean;
  /** Reject 9xxxxx (Army Postal Service) — usually right for a home address. */
  rejectArmyPostal?: boolean;
  label?: string;
  description?: string;
  containerClassName?: string;
}

export function PincodeInput({
  value: controlledValue,
  defaultValue = "",
  onValueChange,
  onValidationChange,
  validateOn = "blur",
  showZone = true,
  rejectArmyPostal = false,
  label,
  description,
  className,
  containerClassName,
  id,
  onBlur,
  ...props
}: PincodeInputProps) {
  const reactId = React.useId();
  const inputId = id ?? `pincode-${reactId}`;
  const messageId = `${inputId}-message`;

  const field = useFieldState<PincodeResult>({
    value: controlledValue,
    defaultValue,
    onValueChange,
    onValidationChange,
    validate: validatePincode,
    transform: (raw) => normalizePincode(raw).slice(0, 6),
    validateOn,
  });

  const armyRejected =
    rejectArmyPostal && field.result.valid && field.result.isArmyPostal
      ? "This is an Army Postal Service code — enter a residential PIN code."
      : undefined;

  const zone =
    showZone && field.result.valid && !armyRejected
      ? field.result.zone
      : undefined;

  return (
    <Field
      id={inputId}
      messageId={messageId}
      label={label}
      message={
        field.error ?? armyRejected ?? field.result.covers ?? description
      }
      tone={
        field.error || armyRejected
          ? "error"
          : field.result.covers
            ? "hint"
            : "muted"
      }
      className={containerClassName}
    >
      <div className="relative">
        <input
          {...props}
          id={inputId}
          type="text"
          inputMode="numeric"
          autoComplete="postal-code"
          placeholder={props.placeholder ?? "560001"}
          value={field.value}
          onChange={(event) => field.setValue(event.target.value)}
          onBlur={(event) => {
            field.markTouched();
            onBlur?.(event);
          }}
          aria-invalid={Boolean(field.error || armyRejected)}
          aria-describedby={messageId}
          className={cn(
            controlClasses({
              error: Boolean(field.error || armyRejected),
              success: field.success && !armyRejected,
            }),
            "tracking-[0.2em]",
            zone && "pr-32",
            className,
          )}
        />
        {zone && <FieldBadge>{zone}</FieldBadge>}
      </div>
    </Field>
  );
}

"use client";

import { type ClassValue, clsx } from "clsx";
import { CircleAlert, Info } from "lucide-react";
import * as React from "react";
import { twMerge } from "tailwind-merge";

/**
 * Shared by every bharat-ui field. Defined here rather than imported from a
 * project's `@/lib/utils` so that installing a component can never overwrite
 * the consumer's own utils file.
 */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export type FieldTone = "error" | "hint" | "muted";

export interface FieldProps {
  id: string;
  /** Id of the element holding the message; wire this into aria-describedby. */
  messageId: string;
  label?: string;
  /** Resolved message text — an error, a warning, or the fallback description. */
  message?: string;
  tone?: FieldTone;
  className?: string;
  children: React.ReactNode;
}

/** Label + control + message, with the aria plumbing already correct. */
export function Field({
  id,
  messageId,
  label,
  message,
  tone = "muted",
  className,
  children,
}: FieldProps) {
  return (
    <div className={cn("w-full", className)}>
      {label && (
        <label htmlFor={id} className="mb-1.5 block text-sm font-medium">
          {label}
        </label>
      )}

      {children}

      {message && (
        <p
          id={messageId}
          // Only errors interrupt a screen reader; hints are read on focus.
          role={tone === "error" ? "alert" : undefined}
          className={cn(
            "mt-1.5 flex items-start gap-1.5 text-xs",
            tone === "error"
              ? "text-red-600 dark:text-red-400"
              : "text-neutral-500 dark:text-neutral-400",
          )}
        >
          {tone === "error" ? (
            <CircleAlert className="mt-px size-3.5 shrink-0" aria-hidden />
          ) : tone === "hint" ? (
            <Info className="mt-px size-3.5 shrink-0" aria-hidden />
          ) : null}
          {message}
        </p>
      )}
    </div>
  );
}

/** Border/ring classes shared by every text control, keyed on validity. */
export function controlClasses(state: {
  error?: boolean;
  success?: boolean;
}): string {
  return cn(
    "h-10 w-full rounded-lg border bg-transparent px-3 py-2 font-mono text-sm outline-none transition",
    "placeholder:font-sans placeholder:text-neutral-400 dark:placeholder:text-neutral-600",
    "disabled:cursor-not-allowed disabled:opacity-50",
    "focus-visible:ring-[3px]",
    state.error
      ? "border-red-500 focus-visible:ring-red-500/20"
      : state.success
        ? "border-emerald-500 focus-visible:ring-emerald-500/20"
        : "border-neutral-300 focus-visible:border-neutral-900 focus-visible:ring-neutral-900/10 dark:border-neutral-700 dark:focus-visible:border-neutral-300 dark:focus-visible:ring-neutral-100/10",
  );
}

export interface ValidationLike {
  valid: boolean;
  error?: { message: string };
}

/**
 * The controlled/uncontrolled + touched + report-upward logic every field here
 * needs. Kept in one place so all of them behave identically: errors appear on
 * blur by default, then update live once the user has been warned.
 */
export function useFieldState<T extends ValidationLike>(options: {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  onValidationChange?: (result: T) => void;
  validate: (raw: string) => T;
  /** Optional input mask applied on every keystroke. */
  transform?: (raw: string) => string;
  validateOn?: "blur" | "change";
}) {
  const {
    value: controlled,
    defaultValue = "",
    onValueChange,
    onValidationChange,
    validate,
    transform,
    validateOn = "blur",
  } = options;

  const isControlled = controlled !== undefined;
  const [uncontrolled, setUncontrolled] = React.useState(defaultValue);
  const value = isControlled ? controlled : uncontrolled;
  const [touched, setTouched] = React.useState(false);

  const result = React.useMemo(() => validate(value), [value, validate]);

  // Report upward only when the outcome actually changes, so consumers can put
  // setState directly in the callback without a render loop.
  const lastReported = React.useRef<string>("");
  React.useEffect(() => {
    const key = JSON.stringify(result);
    if (key === lastReported.current) return;
    lastReported.current = key;
    onValidationChange?.(result);
  }, [result, onValidationChange]);

  const setValue = React.useCallback(
    (next: string) => {
      const masked = transform ? transform(next) : next;
      if (!isControlled) setUncontrolled(masked);
      onValueChange?.(masked);
    },
    [isControlled, onValueChange, transform],
  );

  const shouldValidate = validateOn === "change" || touched;
  const error =
    shouldValidate && value.trim() !== "" ? result.error?.message : undefined;

  return {
    value,
    setValue,
    result,
    touched,
    markTouched: () => setTouched(true),
    error,
    success: result.valid,
  };
}

/** Small right-aligned badge inside a control (bank name, entity type, …). */
export function FieldBadge({ children }: { children: React.ReactNode }) {
  return (
    <span className="pointer-events-none absolute right-2 top-1/2 flex max-w-[45%] -translate-y-1/2 items-center gap-1 truncate rounded-full bg-emerald-500/10 px-2 py-0.5 text-xs font-medium text-emerald-700 dark:text-emerald-400">
      {children}
    </span>
  );
}

/**
 * Indian PIN code (Postal Index Number) validation.
 *
 * Six digits. The first digit is the postal zone, the first two identify the
 * sub-zone/circle, and the remaining digits narrow to a delivery post office.
 * A leading 9 means Army Postal Service rather than a geographic region.
 *
 * We can derive the zone offline, but *not* city and state — that needs a
 * lookup (India Post's PIN API, or a bundled dataset). `PIN_ZONES` is here so a
 * UI can show something useful immediately while the lookup is in flight.
 */

const PINCODE_RE = /^[1-9][0-9]{5}$/;

/** First digit → postal zone and the regions it covers. */
export const PIN_ZONES: Readonly<
  Record<string, { zone: string; covers: string }>
> = {
  "1": {
    zone: "Northern",
    covers: "Delhi, Haryana, Punjab, Himachal Pradesh, J&K, Chandigarh",
  },
  "2": { zone: "Northern", covers: "Uttar Pradesh, Uttarakhand" },
  "3": {
    zone: "Western",
    covers: "Rajasthan, Gujarat, Daman & Diu, Dadra & Nagar Haveli",
  },
  "4": {
    zone: "Western",
    covers: "Maharashtra, Madhya Pradesh, Chhattisgarh, Goa",
  },
  "5": { zone: "Southern", covers: "Andhra Pradesh, Telangana, Karnataka" },
  "6": {
    zone: "Southern",
    covers: "Tamil Nadu, Kerala, Puducherry, Lakshadweep",
  },
  "7": {
    zone: "Eastern",
    covers: "West Bengal, Odisha, Assam, Sikkim, North East, A&N Islands",
  },
  "8": { zone: "Eastern", covers: "Bihar, Jharkhand" },
  "9": {
    zone: "Army Postal Service",
    covers: "APO / FPO — not a geographic region",
  },
};

export type PincodeErrorCode =
  | "empty"
  | "not_digits"
  | "too_short"
  | "too_long"
  | "leading_zero";

export interface PincodeResult {
  valid: boolean;
  normalized: string;
  zone?: string;
  covers?: string;
  /** True for 9xxxxx — a field expecting a home address probably shouldn't accept it. */
  isArmyPostal?: boolean;
  error?: { code: PincodeErrorCode; message: string };
}

function fail(
  code: PincodeErrorCode,
  message: string,
  normalized: string,
): PincodeResult {
  return { valid: false, normalized, error: { code, message } };
}

export function normalizePincode(input: string): string {
  return input.replace(/\D/g, "");
}

export function validatePincode(input: string): PincodeResult {
  const pin = normalizePincode(input);

  if (!input.trim()) return fail("empty", "Enter a PIN code.", pin);
  if (/[^\d\s]/.test(input)) {
    return fail("not_digits", "A PIN code is six digits.", pin);
  }
  if (pin.length < 6) {
    return fail(
      "too_short",
      `A PIN code is 6 digits — ${pin.length} so far.`,
      pin,
    );
  }
  if (pin.length > 6)
    return fail("too_long", "A PIN code is exactly 6 digits.", pin);
  if (pin[0] === "0") {
    return fail("leading_zero", "No Indian PIN code starts with 0.", pin);
  }
  if (!PINCODE_RE.test(pin)) {
    return fail("not_digits", "A PIN code is six digits.", pin);
  }

  const zone = PIN_ZONES[pin[0]];
  return {
    valid: true,
    normalized: pin,
    zone: zone?.zone,
    covers: zone?.covers,
    isArmyPostal: pin[0] === "9",
  };
}
